args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?performer ?performerLabel ?deathDateDBO ?deathDateDBP WHERE {
  dbr:Goodbye_Pork_Pie_Hat dbo:artist ?performer .
  OPTIONAL { ?performer dbo:deathDate ?deathDateDBO . }
  OPTIONAL { ?performer dbp:deathDate ?deathDateDBP . }
  OPTIONAL { ?performer rdfs:label ?performerLabel . FILTER (lang(?performerLabel) = 'en') }
}

